prompt:
{
  "public_instructions": "You translate natural-language access-control requirements into Cedar policies using the supplied schema. Cedar denies by default. An applicable forbid overrides every permit. Guard optional attributes with has before reading them. Preserve the schema's entity, set, and attribute types. Use only the supplied task information. Do not use tools, files, search, additional model calls, or external feedback. Produce a single final answer as a JSON object with exactly one field, policy, whose value is the complete Cedar policy text. Do not include explanations or Markdown fences.
",
  "harness": {
    "instruction_blocks": [
      "Translate the access-control requirements into a complete Cedar policy set. Identify each action, eligible principal, resource type, required condition, prohibition, and exception. Use only entity types, attributes, actions, and representations supported by the schema. Implement the stated permissions and restrictions together.",
      "Before answering, check the policy mentally for both unauthorized permissions and missing required permissions. Keep distinct action rules separate when their conditions differ. Apply exceptions only to the restriction they qualify. Return one final policy set."
    ],
    "input_order": [
      "requirements",
      "schema"
    ],
    "checklist": [
      "Every required action is covered.",
      "Role, ownership, membership, and context conditions follow the requirements.",
      "Prohibitions and exceptions compose correctly.",
      "Optional attribute reads are guarded and Cedar syntax is valid."
    ]
  },
  "requirements": "The system manages switching orders and field execution for electrical grid operations.
The people involved are planners, shift supervisors, operators, control room operators, and auditors.
One person may hold both the planner and shift supervisor roles, and one person may hold both the operator and control room operator roles.
The resources are switching orders and lockout tags.
Every switching order records its planner, executor, feeder, voltage level, circuit count, status, scheduled start, and scheduled end.
Every lockout tag records its order, who applied it, and the feeder.
Each request carries the current time, whether it is on the SCADA network, whether lockout tagout has been verified, and whether an outage emergency has been declared.
An operator or control room operator may execute switching only after the switching order has been authorized.
Neither an operator nor a control room operator may execute switching for an order that has not been authorized.
When the request falls within the order's scheduled switching window, the timing requirement is satisfied.
When the request falls outside the order's scheduled switching window, neither an operator nor a control room operator may execute the switching.
When the number of circuits being switched crosses the threshold for control-room handling, only a control room operator may execute the switching.
When the number of circuits being switched does not cross that threshold, an operator may execute the switching.
A request by an operator to execute a switching that does not trip any prohibition above must be able to succeed.",
  "schema": "entity Person {
    roles: Set<Role>,
};

entity Role enum ["Planner", "ShiftSupervisor", "Operator", "ControlRoomOperator", "Auditor"];

entity Feeder;

entity SwitchingOrderStatus enum ["Authorized", "Unauthorized"];

entity SwitchingOrder {
    planner: Person,
    executor: Person,
    feeder: Feeder,
    voltageLevel: String,
    circuitCount: Long,
    status: SwitchingOrderStatus,
    scheduledStart: datetime,
    scheduledEnd: datetime,
    requiresControlRoomHandling: Bool,
};

entity LockoutTag {
    order: SwitchingOrder,
    appliedBy: Person,
    feeder: Feeder,
};

action executeSwitching appliesTo {
    principal: [Person],
    resource: [SwitchingOrder],
    context: {
        currentTime: datetime,
        onScadaNetwork: Bool,
        lockoutTagoutVerified: Bool,
        outageEmergencyDeclared: Bool,
    },
};
"
}
